          {{ include('ui/box/box.html.twig', {'p': {'Class': 'flex aspect-video items-center justify-center rounded bg-muted text-foreground', 'Attrs': ui_attrs(['data-testid', 'showcase-panel'])}, 'children': c_1}, with_context = false) }}
