  {{ include('ui/box/box.html.twig', {'p': {'Class': ui_s((ui_t(ui_eq(v_cols, '4')) ? 'grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-3'))}, 'children': c_7}, with_context = false) }}
